function addWithoutPlus(a: number, b: number): number {
  let result = 0, carry = 0;
  // bit walks 1, 2, 4, …, 2^31; one more << 1 leaves 0 in 32-bit math
  for (let bit = 1; bit !== 0; bit <<= 1) {
    const x = a & bit ? 1 : 0, y = b & bit ? 1 : 0;
    if (x ^ y ^ carry) result |= bit;
    carry = (x & y) | (x & carry) | (y & carry);
  }
  return result; // already a signed 32-bit value
}

