class Solution:
    def addWithoutPlus(self, a: int, b: int) -> int:
        MASK = 0xFFFFFFFF
        result, carry = 0, 0
        for i in range(32):
            x, y = (a >> i) & 1, (b >> i) & 1  # >> on a negative int still reads its two's-complement bits
            result |= (x ^ y ^ carry) << i
            carry = (x & y) | (x & carry) | (y & carry)
        # bit 31 set means negative: flip back to Python's infinite sign bits
        return result if result <= 0x7FFFFFFF else ~(result ^ MASK)

