    def addWithoutPlus(self, a: int, b: int) -> int:
        MASK = 0xFFFFFFFF  # simulate a 32-bit register
        a, b = a & MASK, b & MASK
        while b:
            a, b = a ^ b, ((a & b) << 1) & MASK
        # above 0x7FFFFFFF the sign bit is set: equals a - 2**32, written without minus
        return a if a <= 0x7FFFFFFF else ~(a ^ MASK)

